import{c as t,Q as a,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const x=JSON.parse('{"title":"LLM Agents Are Latent Context Managers: Eliciting Self-Managed Context via State Proprioception","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.30005","title":"LLM Agents Are Latent Context Managers: Eliciting Self-Managed Context via State Proprioception","arxiv_id":2606.30005,"collected_at":"2026-08-04T00:00:00.000Z","collected_by":"routine-d","domain":"Context Engineering","pdf_path":"pdfs/2606.30005.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-08-04-llm-agents-latent-context-managers-state-proprioception-2606-30005.md","filePath":"research/papers/2026-08-04-llm-agents-latent-context-managers-state-proprioception-2606-30005.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-08-04-llm-agents-latent-context-managers-state-proprioception-2606-30005.md"};function i(s,e,l,c,p,g){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="llm-agents-are-latent-context-managers-eliciting-self-managed-context-via-state-proprioception" tabindex="-1">LLM Agents Are Latent Context Managers: Eliciting Self-Managed Context via State Proprioception <a class="header-anchor" href="#llm-agents-are-latent-context-managers-eliciting-self-managed-context-via-state-proprioception" aria-label="Permalink to &quot;LLM Agents Are Latent Context Managers: Eliciting Self-Managed Context via State Proprioception&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>長程工具型 agent 的瓶頸在於 context 逐步逼近 window 上限。既有方法多從 agent 或系統層面控制 context，卻忽略一個根本問題：前沿語言模型對自身 context 狀態是「本體感覺盲」（proprioceptively blind）。作者提出 VISTA（Visible Internal State for Tool Agents），一套免訓練系統，將工作記憶表示為型別化區塊，並在執行期向 agent 公開 token 用量、近期性追蹤、歸檔狀態與剩餘預算。實驗顯示多個 benchmark 上有顯著提升，且效益隨 context 壓力升高而放大，跨不同模型骨幹保持一致。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>「本體感覺盲」的診斷與 workspace 的「行為信號優先」監控哲學相通——本文提出的解法是把 context 狀態顯式暴露給模型本身，而非僅靠外部監控數字，可作為 context-management.md 未來擴充「模型自我感知 context 用量」機制時的參考設計。</p>',5)])])}const m=t(r,[["render",i]]);export{x as __pageData,m as default};
